sys_script_include.script:
var ExtractionMapper = Class.create();

// The published mapping that turns the AI payload into staging rows (see
// x_gegis_ins_policy_mapping). The legacy extraction_mapping table is used only
// when that mapping is not active - kept so an instance without the V2 seed still runs.
ExtractionMapper.MAPPING_CODE = 'AI_TO_SUBMISSION';

ExtractionMapper.prototype = {
    initialize: function() {
        this.MAPPING = 'x_gegis_ins_policy_extraction_mapping';
        this.ENTITY = 'x_gegis_ins_policy_extraction_entity';
        this.FIELD = 'x_gegis_ins_policy_extraction_field';
        this.P = 'x_gegis_ins_policy_';
    },

    /**
     * Shred a parsed AI payload into staging rows for one extraction version.
     * Leaf values may be scalars or objects of the form
     * { value: ..., confidence: 0.93, page: 2, bbox: 'x,y,w,h' }.
     *
     * @param extractionGr GlideRecord x_gegis_ins_policy_extraction (inserted)
     * @param payload Object parsed raw JSON from the AI service
     * @return Number of extraction_field rows created
     */
    mapPayload: function(extractionGr, payload) {
        var mappingId = this._activeMapping();
        if (mappingId)
            return this._mapWithRules(extractionGr, payload, mappingId);
        return this._mapLegacy(extractionGr, payload);
    },

    // ---------------------------------------------------------------- V2: mapping rules
    _activeMapping: function() {
        var m = new GlideRecord(Constants.TABLE.MAPPING);
        if (!m.isValid())
            return '';
        m.addQuery('code', ExtractionMapper.MAPPING_CODE);
        m.addQuery('active', true);
        m.addQuery('status', Constants.CHOICE.CATALOG_STATUS.PUBLISHED);
        m.orderByDesc('version');
        m.setLimit(1);
        m.query();
        return m.next() ? m.getUniqueValue() : '';
    },

    _mapWithRules: function(extractionGr, payload, mappingId) {
        var result = new MappingEngine().transform(mappingId, payload || {});
        for (var e = 0; e < result.errors.length; e++)
            gs.warn('[ExtractionMapper] ' + result.errors[e]);
        var created = 0;
        var entityCache = {};
        for (var i = 0; i < result.rows.length; i++) {
            var row = result.rows[i];
            if (!row.target_table || !row.target_column)
                continue;
            if ((row.raw === '' || row.raw === undefined) && (row.value === '' || row.value === undefined))
                continue;
            var entityType = row.target_table.indexOf(this.P) === 0 ? row.target_table.substring(this.P.length) : row.target_table;
            var entityId = entityType === 'submission' ? '' :
                this._entity(extractionGr, entityType, row.context_index, entityCache);
            var f = new GlideRecord(this.FIELD);
            f.initialize();
            f.extraction = extractionGr.getUniqueValue();
            f.entity = entityId;
            f.field_path = row.source_ref || row.target_path;
            f.extracted_value = row.raw !== '' ? String(row.raw) : String(row.value);
            f.mapped_value = String(row.value);
            f.confidence = row.confidence;
            f.page_number = row.page;
            f.bounding_box = row.bbox;
            f.target_table = row.target_table;
            f.target_column = row.target_column;
            f.data_type = this._dataType(row.transform);
            f.mapping_rule = row.rule;
            f.review_status = 'needs_review';
            f.insert();
            created++;
        }
        return created;
    },

    _entity: function(extractionGr, entityType, index, cache) {
        var key = entityType + ':' + index;
        if (cache[key])
            return cache[key];
        var e = new GlideRecord(this.ENTITY);
        e.initialize();
        e.extraction = extractionGr.getUniqueValue();
        e.entity_type = entityType;
        e.entity_index = index;
        e.label = entityType.replace(/_/g, ' ') + ' ' + (index + 1);
        e.match_status = 'new';
        e.disposition = 'pending';
        cache[key] = e.insert();
        return cache[key];
    },

    _dataType: function(transform) {
        var T = Constants.CHOICE.MAPPING_TRANSFORM;
        if (transform === T.NUMBER_FORMAT || transform === T.CURRENCY_CONVERT)
            return 'decimal';
        if (transform === T.DATE_FORMAT)
            return 'date';
        if (transform === T.VALUE_MAP || transform === T.LOOKUP)
            return 'choice';
        return 'string';
    },

    // ---------------------------------------------------------------- legacy: extraction_mapping
    _mapLegacy: function(extractionGr, payload) {
        var created = 0;
        var entityCache = {};
        var lob = payload && payload.line_of_business ? String(payload.line_of_business) : 'all';

        var m = new GlideRecord(this.MAPPING);
        m.addActiveQuery();
        m.addQuery('line_of_business', 'IN', 'all,' + lob);
        m.orderBy('order');
        m.query();
        while (m.next()) {
            var hits = this._resolvePath(payload, String(m.field_path));
            for (var i = 0; i < hits.length; i++) {
                var hit = hits[i];
                if (hit.value === undefined || hit.value === null || hit.value === '')
                    continue;
                var entityId = this._ensureEntity(extractionGr, m, hit, entityCache);
                this._createField(extractionGr, m, hit, entityId);
                created++;
            }
        }
        return created;
    },

    /**
     * Resolve a mapping path against the payload. Supports dot paths and one
     * repeating segment, e.g. 'insured.name' or 'locations[*].street'.
     * Returns [{ value, index, path }] where index is the repeating-group
     * ordinal (-1 for non-repeating paths).
     */
    _resolvePath: function(payload, path) {
        var star = path.indexOf('[*]');
        if (star === -1) {
            var v = this._walk(payload, path);
            return v === undefined ? [] : [{ value: v, index: -1, path: path }];
        }
        var head = path.substring(0, star);
        var tail = path.substring(star + 4); // skip '[*].'
        var arr = this._walk(payload, head);
        if (!arr || !arr.length)
            return [];
        var out = [];
        for (var i = 0; i < arr.length; i++) {
            var v2 = tail ? this._walk(arr[i], tail) : arr[i];
            if (v2 !== undefined)
                out.push({ value: v2, index: i, path: head + '[' + i + '].' + tail });
        }
        return out;
    },

    _walk: function(obj, path) {
        if (!path)
            return obj;
        var parts = path.split('.');
        var cur = obj;
        for (var i = 0; i < parts.length; i++) {
            if (cur === null || cur === undefined)
                return undefined;
            cur = cur[parts[i]];
        }
        return cur;
    },

    /** Create (or reuse) the extraction_entity row for a repeating group. */
    _ensureEntity: function(extractionGr, mapping, hit, cache) {
        var entityType = String(mapping.entity_type);
        if (!entityType || entityType === 'submission')
            return '';
        var key = entityType + ':' + hit.index;
        if (cache[key])
            return cache[key];
        var e = new GlideRecord(this.ENTITY);
        e.initialize();
        e.extraction = extractionGr.getUniqueValue();
        e.entity_type = entityType;
        e.entity_index = hit.index < 0 ? 0 : hit.index;
        e.label = entityType + (hit.index >= 0 ? ' ' + (hit.index + 1) : '');
        e.match_status = 'new';
        e.disposition = 'pending';
        cache[key] = e.insert();
        return cache[key];
    },

    _createField: function(extractionGr, mapping, hit, entityId) {
        var raw = hit.value;
        var value = raw, confidence = '', page = '', bbox = '';
        if (raw !== null && typeof raw === 'object') {
            value = raw.value;
            confidence = raw.confidence !== undefined ? raw.confidence : '';
            page = raw.page !== undefined ? raw.page : '';
            bbox = raw.bbox || '';
        }
        var f = new GlideRecord(this.FIELD);
        f.initialize();
        f.extraction = extractionGr.getUniqueValue();
        f.entity = entityId;
        f.field_path = hit.path;
        f.extracted_value = String(value);
        f.mapped_value = String(value);
        f.confidence = confidence;
        f.page_number = page;
        f.bounding_box = bbox;
        f.target_table = String(mapping.target_table);
        f.target_column = String(mapping.target_column);
        f.data_type = String(mapping.data_type);
        f.review_status = 'needs_review';
        f.insert();
    },

    type: 'ExtractionMapper'
};
